template:
fn first_word⟦generics⟧(text: &'a str, label: ⟦label_ty⟧) -> &'a str {
    println!("[{label}]");
    text.split_whitespace().next().unwrap_or(text)
}

fn main() {
    let text = String::from("hello world");
    let result;
    {
        let label = String::from("query");
        result = first_word(&text, &label);
    }
    println!("{result}");
}
